Consider the following Python class definition:

```python
class Descriptor:
    def __init__(self, value=None):
        self.value = value
    def __get__(self, obj, owner):
        if obj is None:
            return self
        return self.value * 2
    def __set__(self, obj, value):
        self.value = value

class MyClass:
    attr = Descriptor(5)
    def __init__(self):
        self.instance_attr = 10
    def __getattr__(self, name):
        return f\"missing {name}\"
    def __getattribute__(self, name):
        if name == 'special':
            return 42
        return object.__getattribute__(self, name)
```

Which of the following statements are true when executing the code below?

```python
obj = MyClass()
print(obj.attr)
print(obj.instance_attr)
print(obj.special)
print(obj.missing)
```
